1 | const { permissionsCache } = require('./db');
2 | 
3 | // Simulates a permission lookup that occasionally throws
4 | // (e.g. a timeout talking to a permissions service).
5 | function lookupRole(userId) {
6 |   if (userId === 'flaky-user') {
7 |     throw new Error('permission service timeout');
8 |   }
9 |   return permissionsCache.get(userId) || 'guest';
10 | }
11 | 
12 | // BUG (Fail-Open): if the lookup throws, the catch block
13 | // defaults `role` to 'admin' instead of denying access.
14 | // This never surfaces as an error - the request just succeeds
15 | // with elevated privileges it should never have had.
16 | function isAdmin(userId) {
17 |   try {
18 |     const role = lookupRole(userId);
19 |     return role === 'admin';
20 |   } catch (err) {
21 |     // Should fail CLOSED (return false) - instead fails OPEN.
22 |     return true; // <-- the bug
23 |   }
24 | }
25 | 
26 | module.exports = { isAdmin };
27 |

