Contents of file src/lib/fetchWithRetry.js:

1 | // Simulates fetching live pricing data from an external service
2 | // that is currently down (always throws, for demo purposes).
3 | async function fetchLivePrice(itemId) {
4 |   throw new Error('pricing service unavailable');
5 | }
6 | 
7 | let staleCache = { itemId: 'widget-1', price: 9.99, cachedAt: 'yesterday' };
8 | 
9 | // BUG (Swallowed Error): retries 3 times, and when all 3 fail,
10 | // silently returns stale cached data as if it were fresh -
11 | // no error, no warning, no flag on the response indicating
12 | // the data is stale. Callers have no way to know they're
13 | // looking at old data.
14 | async function getPriceWithRetry(itemId) {
15 |   for (let attempt = 1; attempt <= 3; attempt++) {
16 |     try {
17 |       return await fetchLivePrice(itemId);
18 |     } catch (err) {
19 |       if (attempt === 3) {
20 |         return staleCache; // <-- the bug: silently returns stale data
21 |       }
22 |     }
23 |   }
24 | }
25 | 
26 | module.exports = { getPriceWithRetry };
27 |

