Contents of file src/routes/leaderboard.js:

1 | const express = require('express');
2 | const router = express.Router();
3 | const { leaderboard } = require('../lib/db');
4 | 
5 | // POST /leaderboard/:userId/score - updates a user's score.
6 | // BUG (Race Condition): reads-then-writes with an artificial
7 | // delay (simulating a real async DB round trip) and no locking.
8 | // Two concurrent requests can interleave so the LOSER of the
9 | // race overwrites the WINNER, with no error and no indication
10 | // anything went wrong - the leaderboard just quietly shows a
11 | // lower score than it should.
12 | router.post('/:userId/score', async (req, res) => {
13 |   const { userId } = req.params;
14 |   const { newScore } = req.body;
15 | 
16 |   const current = leaderboard.get(userId) || { score: 0 };
17 | 
18 |   // Simulated async I/O delay - this is where the race window opens.
19 |   await new Promise((resolve) => setTimeout(resolve, Math.random() * 50));
20 | 
21 |   // Only writes if newScore is higher... using the STALE `current`
22 |   // read from before the delay, not a fresh read. Two concurrent
23 |   // requests can both read the same stale `current` and both decide
24 |   // to write, with whichever finishes last "winning" regardless of
25 |   // which score is actually higher.
26 |   if (newScore > current.score) {
27 |     leaderboard.set(userId, { score: newScore, updatedAt: Date.now() });
28 |   }
29 | 
30 |   res.json({ status: 'ok' });
31 | });
32 | 
33 | router.get('/:userId', (req, res) => {
34 |   res.json(leaderboard.get(req.params.userId) || { score: 0 });
35 | });
36 | 
37 | module.exports = router;
38 |

