1 | const express = require('express');
2 | const router = express.Router();
3 | const { users } = require('../lib/db');
4 | 
5 | // POST /profile - saves a user profile
6 | // BUG (Data Contract Mismatch): writes the field as `user_name`,
7 | // but GET /profile and the rest of the app read `username`.
8 | // No error is thrown anywhere - the field is just silently absent
9 | // wherever it's read, and appears as `undefined`.
10 | router.post('/profile', (req, res) => {
11 |   const { id, user_name, email } = req.body;
12 |   users.set(id, { id, user_name, email }); // <-- should be `username`
13 |   res.json({ status: 'ok' });
14 | });
15 | 
16 | // GET /profile/:id - reads a user profile
17 | router.get('/profile/:id', (req, res) => {
18 |   const user = users.get(req.params.id) || {};
19 |   // Reads `username`, which was never written by POST /profile above.
20 |   res.json({ id: user.id, username: user.username, email: user.email });
21 | });
22 | 
23 | module.exports = router;
